def clamp(value, lo, hi):
    if value < lo:
        return lo
    if value > hi:
        return hi
    return value

def is_palindrome(s):
    normalized = [c.lower() for c in s if c.isalnum()]
    return normalized == normalized[::-1]

def average(nums):
    if not nums:
        return None
    return sum(nums) / len(nums)

def safe_divide(a, b):
    if b == 0:
        raise ValueError('division by zero')
    return a / b

def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

